changeSet.sql:
UPDATE m_charge SET is_active = false , "name" = CONCAT("name",' --DISABLED') WHERE "name" LIKE '%Capital Pendiente MiPyme%' OR "name" LIKE '%Capital Pendiente My Pyme%';
UPDATE m_product_loan SET "name" = CONCAT("name",' --DISABLED') , short_name = '*001' , close_date = (CURRENT_DATE - INTERVAL '1 day') WHERE "name" = 'Microcredito';
UPDATE m_product_loan SET "name" = CONCAT("name",' --DISABLED') , short_name = '*002' , close_date = (CURRENT_DATE - INTERVAL '1 day') WHERE "name" = 'Microcredito B';
UPDATE m_product_loan SET "name" = CONCAT("name",' --DISABLED') , short_name = '*003' , close_date = (CURRENT_DATE - INTERVAL '1 day') WHERE "name" = 'MicrocreditoM';


